@using sv_c95d5390ce25411d9164a56bf7940c76.Models

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status"
                @onclick="() => OnStepClick(stepIndex)"
                role="button"
                aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-circle">
                    @if (CompletedSteps.Contains(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@using sv_c95d5390ce25411d9164a56bf7940c76.Models

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="John Doe" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="john@example.com" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" placeholder="123 Main St, City, State" />
    </div>

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@using sv_c95d5390ce25411d9164a56bf7940c76.Models

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString(\"yyyy-MM-dd\")); NotifyChanged(); }" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@EndDate?.ToString("yyyy-MM-dd")" @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @oninput="e => { Description = e.Value?.ToString() ?? \"\"; NotifyChanged(); }"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Index, Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync(Index);
    }

    public record WorkEntryData(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

@using sv_c95d5390ce25411d9164a56bf7940c76.Models
@using static sv_c95d5390ce25411d9164a56bf7940c76.Components.Pages.Apply.WorkEntryForm

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        var index = i;
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="HandleEntryChanged"
                       OnRemove="HandleRemove" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryState> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryState>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntryState());
        }
    }

    private void HandleEntryChanged(WorkEntryData data)
    {
        if (data.Index < Entries.Count)
        {
            Entries[data.Index] = new WorkEntryState
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (Entries.Count > 1 && index < Entries.Count)
        {
            Entries.RemoveAt(index);
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryState());
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryState
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@using sv_c95d5390ce25411d9164a56bf7940c76.Models
@using static sv_c95d5390ce25411d9164a56bf7940c76.Components.Pages.Apply.ReferenceForm

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var r = References[i];
        var index = i;
        <ReferenceForm Index="index"
                       Name="@r.Name"
                       Relationship="@r.Relationship"
                       Email="@r.Email"
                       Phone="@r.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnChanged="HandleChanged"
                       OnRemove="HandleRemove" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceState> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceState>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (References.Count < 2)
        {
            while (References.Count < 2)
            {
                References.Add(new ReferenceState());
            }
        }
    }

    private void HandleChanged(ReferenceData data)
    {
        if (data.Index < References.Count)
        {
            References[data.Index] = new ReferenceState
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (References.Count > 2 && index < References.Count)
        {
            References.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceState());
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    public class ReferenceState
    {
