arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_c95d5390ce25411d9164a56bf7940c76.Models
@using sv_c95d5390ce25411d9164a56bf7940c76.Components.Pages.Apply
@using static sv_c95d5390ce25411d9164a56bf7940c76.Components.Pages.Apply.WorkHistoryStep
@using static sv_c95d5390ce25411d9164a56bf7940c76.Components.Pages.Apply.ReferencesStep
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnNavigateToStep="NavigateToStep" />

    <div class="step-container">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@personalInfo.FullName"
                                  Email="@personalInfo.Email"
                                  Phone="@personalInfo.Phone"
                                  Address="@personalInfo.Address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetterText="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            OnBack="GoBack"
                            OnEditStep="NavigateToStep"
                            SubmitApplication="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo personalInfo = new("", "", "", "");
    private List<WorkEntryState> workEntries = new() { new WorkEntryState() };
    private List<ReferenceState> references = new() { new ReferenceState(), new ReferenceState() };
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryState> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceState> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var workHistory = new WorkHistory(
            workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description
            )).ToList()
        );

        var refList = references.Select(r => new Reference(
            r.Name, r.Relationship, r.Email, r.Phone
        )).ToList();

        var application = new JobApplication(personalInfo, workHistory, refList, coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s ease;
}

.step-item.active .step-circle {
    background: #4361ee;
    color: #fff;
    border-color: #4361ee;
}

.step-item.completed .step-circle {
    background: #2ecc71;
    color: #fff;
    border-color: #2ecc71;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step-item.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #2ecc71;
}

.step-item.future .step-label {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-container {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h3 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.3rem;
    font-size: 0.85rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn-outline {
    background: transparent;
    border: 1px solid #4361ee;
    color: #4361ee;
}

.btn-outline:hover {
    background: #f0f4ff;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger-sm {
    background: #e74c3c;
    color: #fff;
    border: none;
    padding: 0.3rem 0.8rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #c0392b;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-link:hover {
    color: #3451d1;
}

.btn-submit {
    font-size: 1.05rem;
    padding: 0.8rem 2rem;
}

/* Validation */
.validation-error {
    background: #ffeef0;
    border: 1px solid #e74c3c;
    color: #c0392b;
    padding: 0.6rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.3rem;
}

/* Work Entry / Reference Forms */
.work-entry-form,
.reference-form {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.2rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.8rem;
}

.entry-header h4,
.reference-form h4 {
    margin: 0 0 0.5rem 0;
    color: #333;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h4 {
    margin: 0 0 0.5rem 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #555;
    font-size: 0.9rem;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-entry {
    padding: 0.5rem 0;
}

.review-entry + .review-entry {
    border-top: 1px solid #f0f0f0;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    max-height: 200px;
    overflow-y: auto;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h4 {
    color: #2ecc71;
    font-size: 1.3rem;
}

.submission-confirmation p {
    font-size: 1.05rem;
    color: #333;
}

