@using sv_c95d5390ce25411d9164a56bf7940c76.Models

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        var index = i;
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="HandleEntryChanged"
                       OnRemove="HandleRemove" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryState> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryState>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntryState());
        }
    }

    private void HandleEntryChanged(WorkEntryData data)
    {
        if (data.Index < Entries.Count)
        {
            Entries[data.Index] = new WorkEntryState
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private void HandleRemove(int index)
    {
        if (Entries.Count > 1 && index < Entries.Count)
        {
            Entries.RemoveAt(index);
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryState());
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

