        {
            <button class="btn btn-danger-sm" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @oninput="OnCompanyInput" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @oninput="OnTitleInput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd"))" @onchange="OnEndDateChange" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="OnCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" @oninput="OnDescriptionInput">@Description</textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }

    private void OnCompanyInput(ChangeEventArgs e)
    {
        Company = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void OnTitleInput(ChangeEventArgs e)
    {
        Title = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void OnStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            StartDate = date;
        NotifyChanged();
    }

    private void OnEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnCurrentChange(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void OnDescriptionInput(ChangeEventArgs e)
    {
        Description = e.Value?.ToString() ?? "";
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Index, Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync(Index);
    }
}

